def test_intrange_accepts_inclusive_lower_boundary():
    import click
    from click.testing import CliRunner

    received = []

    @click.command()
    @click.option("--count", type=click.IntRange(1, 3))
    def command(count):
        received.append(count)

    runner = CliRunner()
    for value, expected in (("1", 1), ("3", 3)):
        result = runner.invoke(command, ["--count", value])
        assert result.exit_code == 0
        assert received[-1] == expected
        assert isinstance(received[-1], int) and not isinstance(received[-1], bool)

